"""Memory validation tools for ``set_fields`` and correction direct writes.

Builders may define internal ``run_after_setting_<item>`` tools to validate or
derive state after the engine writes a settable memory entry. These tools are
discovered by name prefix, hidden from the LLM tool list, and run only for
top-level ``set_fields`` / correction writes — not for writes made inside a
memory validation tool (see
:meth:`~rasa.mantle.state.tracker_handle.TrackerHandle.suppress_memory_validation_tools`).
"""

from __future__ import annotations

import json
from typing import TYPE_CHECKING, Any

from rasa.shared.core.events import create_memory_write_event

if TYPE_CHECKING:
    from rasa.mantle.memory.manager import MemoryManager
    from rasa.mantle.state.tracker_handle import TrackerHandle

MEMORY_VALIDATION_TOOL_PREFIX = "run_after_setting_"


def is_memory_validation_tool(tool_name: str) -> bool:
    """Return ``True`` when *tool_name* is a memory validation tool."""
    return tool_name.startswith(MEMORY_VALIDATION_TOOL_PREFIX)


def memory_validation_tool_name(entry_name: str) -> str:
    """Return the memory validation tool name for a settable memory *entry_name*."""
    return f"{MEMORY_VALIDATION_TOOL_PREFIX}{entry_name}"


def snapshot_accessible_memory(
    memory: "MemoryManager", skill_id: str, flow_id: str
) -> dict[str, Any]:
    """Capture current values for every memory entry readable in scope."""
    return {
        slot_name: entry.value
        for slot_name, entry in memory.read_all(skill_id, flow_id).items()
    }


def restore_memory_snapshot(handle: "TrackerHandle", snapshot: dict[str, Any]) -> None:
    """Restore tracker slots to a prior :func:`snapshot_accessible_memory` state.

    Rollback writes ``MemorySet`` / ``MemoryCleared`` events directly rather
    than going through :meth:`MemoryManager.set`. The manager rejects
    undeclared and write-once project fields — but a rollback must faithfully
    revert *whatever* a rejected memory validation tool wrote. Routing rollback through
    ``memory.set`` would refuse to undo exactly those writes, so we restore the
    slot values directly.
    """
    events = []
    for slot_name, value in snapshot.items():
        if handle.get_slot(slot_name) != value:
            events.append(create_memory_write_event(slot_name, value))
    if not events:
        return
    with handle.recording_write(tool=None, arguments={}):
        handle.apply_events(events)


def tool_result_indicates_error(result: str) -> bool:
    """Return ``True`` when an in-process tool returned a JSON error payload.

    Only a *non-null* ``error`` value counts: these tools routinely return
    ``{"error": None, ...}`` on success, and treating that as a failure would
    roll back a perfectly good write.
    """
    try:
        payload = json.loads(result)
    except json.JSONDecodeError:
        return False
    return isinstance(payload, dict) and payload.get("error") is not None


def extract_tool_error_message(result: str) -> str:
    """Return the human-readable error from a JSON tool-result string."""
    try:
        payload = json.loads(result)
    except json.JSONDecodeError:
        return result
    if isinstance(payload, dict) and payload.get("error") is not None:
        return str(payload["error"])
    return result
